efault([]) // [\"React Hooks - MDN\", \"Clean Code - Kitap\"]\n  nextSteps          String[] @default([]) // Somut eylem planı\n  encouragementQuote String? // Günlük motivasyon sözü\n\n  // Orijinal JSON (audit)\n  rawJson Json\n\n  intern User @relation(\"InternAiReports\", fields: [internId], references: [id], onDelete: Cascade)\n}\n\n// 9. DEPARTMAN MODELİ\nmodel Department {\n  id          Int      @id @default(autoincrement())\n  name        String   @unique // Departman adı (benzersiz)\n  description String?  @db.Text // Opsiyonel açıklama\n  color       String   @default(\"#0084ff\") // UI'da kullanılacak renk kodu\n  createdAt   DateTime @default(now())\n\n  // 🔄 İLİŞKİ: Bu departmana bağlı kullanıcılar\n  members User[]\n}\n"
